                            <path stroke="currentColor" stroke-width="1.00" stroke-linecap="round" stroke-linejoin="round" stroke-miterlimit="4.00" style="stroke: ${color}; stroke-opacity: 0.5; stroke-width: 1px; stroke-linejoin: round; fill: ${tccolor}; fill-opacity: 0.5;" d="M 7.5 0.5 L 16.5 0.5 A 7 7 0 0 1 23.5 7.5 L 23.5 7.5 A 7 7 0 0 1 16.5 14.5 L 8.5 14.5 L 5.192 16.5 L 5.5 14.5 A 7 7 30 0 1 0.5 7.5 L 0.5 7.5 A 7 7 0 0 1 7.5 0.5 Z"/>
